import json, re, sys, urllib.request, io, math
import numpy as np
from PIL import Image

UA = {"android":"com.google.android.youtube/20.10.38 (Linux; U; Android 11) gzip"}

def player(vid):
    body = json.dumps({"context":{"client":{"clientName":"ANDROID","clientVersion":"20.10.38","androidSdkVersion":30,"hl":"en"}},"videoId":vid}).encode()
    req = urllib.request.Request("https://www.youtube.com/youtubei/v1/player?key=AIzaSyAO_FJ2SlqU8Q--5rnJlEIdPZiW-p6DHAA&prettyPrint=false",
        data=body, headers={"Content-Type":"application/json","User-Agent":UA["android"]})
    d = json.loads(urllib.request.urlopen(req, timeout=60).read())
    spec = d.get('storyboards',{}).get('playerStoryboardSpecRenderer',{}).get('spec')
    length = float(d.get('videoDetails',{}).get('lengthSeconds', 0))
    return length, spec

def fetch(url):
    req = urllib.request.Request(url, headers={"User-Agent":"Mozilla/5.0"})
    with urllib.request.urlopen(req, timeout=60) as r:
        return r.read()

def load(vid):
    length, spec = player(vid)
    if not spec:
        print(f"{vid}: NO storyboards, len={length}"); return None
    parts = spec.split('|')
    base = parts[0]
    levels = []
    for p in parts[1:]:
        f = p.split('#')
        levels.append(dict(w=int(f[0]), h=int(f[1]), interval=int(f[2]), M=int(f[3]), N=int(f[4])))
    lvl = max(range(len(levels)), key=lambda i: levels[i]['w'])
    L = levels[lvl]
    cols = int(math.ceil(math.sqrt(L['N'])))
    rows = int(math.ceil(L['N'] / cols))
    tw, th = L['w']//cols, L['h']//rows
    print(f"{vid}: len={length:.0f}s best={L['w']}x{L['h']} grid={cols}x{rows} frame={tw}x{th} interval={L['interval']}ms pages={L['M']}")
    frames = []
    for n in range(L['M']):
        url = base.replace('$L', str(lvl)).replace('$N', str(n))
        img = Image.open(io.BytesIO(fetch(url))).convert('RGB')
        arr = np.asarray(img).astype(np.float64)
        for r in range(rows):
            for c in range(cols):
                if r*cols+c >= L['N']: continue
                cell = arr[r*th:(r+1)*th, c*tw:(c+1)*tw]
                frames.append(cell.mean(axis=(0,1)))
    frames = np.array(frames)
    print(f"   frames={len(frames)} -> {length/len(frames):.2f}s per frame")
    return dict(vid=vid, length=length, frames=frames.tolist())

if __name__ == '__main__':
    vids = {
      'A_zombie':'6Ejga4kJUts','B_bumbum':'_P7S2lKif-A','C_intheend':'eVTXPUF4Oz4','D_spirit':'hTWKbfoikeg',
      'E_novrain':'8SbUC-UaAxE','F_takeonme':'djV11Xbc914','G_sweetchild':'1w7OgIMMRc4','H_believer':'7wtfhZwyrcc',
      'I_jtywy':'LjhCEhWiKXk','J_bohrhap':'fJ9rUzIMcZQ'}
    out = {}
    for k,v in vids.items():
        try:
            d = load(v)
            if d: out[k] = d
        except Exception as e:
            print(f"{k}: ERROR {e}")
    json.dump(out, open('sb_data.json','w'))
    print("saved:", list(out.keys()))
EOF
